nume = T(:,1); expr = T(:,3);
v = evalueaza_fusion(nume, expr);
val = @(n) v(strcmp(nume, n));

% Verificări: expresiile Fusion dau aceleași valori ca scripturile
xd = cinematica(P.thEO_deschis, P)*mm; xi = cinematica(P.thEO_inchis, P)*mm; xt = cinematica(P.thTO, P)*mm;
verifica(abs(val('x_EO_deschis') - xd) < 1e-9 && abs(val('x_EO_inchis') - xi) < 1e-9 && abs(val('x_TO') - xt) < 1e-9, ...
         'F7a', 'Expresiile ferestrelor din Fusion dau aceleași cote ca s01');
verifica(abs(val('cursa_servo_cvt') - 2*(P.r1_max - P.r1_min)*tan(P.beta*pi/180)*mm) < 1e-9, ...
         'F7b', 'Cursa servo-ului din Fusion = s03');
verifica(abs(val('raza_max_contragr') - (P.h_comp + P.L - P.r - (P.S + P.joc_raclor + P.zona_raclor) - P.joc_cg)*mm) < 1e-9, ...
         'F7c', 'Raza maximă a contragreutăților din Fusion = s06');
verifica(abs(val('latime_transfer') - P.w_tr*mm) < 1e-9, ...
         'F7e', 'Lățimea totală din Fusion (A, B, boost) = cea din timp-arie');
verifica(abs(val('diametru_piston') - (P.B - mean(P.joc_piston))*mm) < 1e-9, ...
         'F7d', 'Diametrul pistonului din Fusion = alezajul minus jocul mediu');
verifica(abs(val('y_capac_int') - D.y_int*mm) < 1e-9 && abs(val('y_capac_ext') - D.y_ext*mm) < 1e-9 && abs(val('capac_raza_int') - D.R_int*mm) < 1e-9, ...
         'F7f', 'Fețele și tamburul capacului din dreapta din Fusion = s18');

% Comentariile primesc valoarea calculată, ca s-o compari în Fusion
if ~exist('fusion', 'dir'), mkdir('fusion'); end
fid = fopen(fullfile('fusion', 'parametri_fusion.csv'), 'w', 'n', 'UTF-8');
fprintf(fid, 'Nume,Unitate,Expresie,Comentariu\n');
for k = 1:size(T, 1)
    fprintf(fid, '"%s","%s","%s","%s (MATLAB: %.3f %s)"\n', T{k,1}, T{k,2}, T{k,3}, T{k,4}, v(k), T{k,2});
end
fclose(fid);
fprintf('Am scris %d parametri în fusion/parametri_fusion.csv\n', size(T, 1));
fprintf('Fereastra de evacuare: %.2f mm sub PMI; transferul: %.2f mm; cursa supapei: %.2f mm\n', ...
        val('x_EO_deschis'), val('x_TO'), val('cursa_supapa'));

